package com.sisge.ms.entity;
import jakarta.persistence.*; import java.time.Instant; import com.sisge.ms.entity.Organizacion; import com.sisge.ms.entity.Rol;
@Entity @Table(name="usuario_organizacion",uniqueConstraints=@UniqueConstraint(columnNames={"usuario_id","organizacion_id"})) public class UserOrganization { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne @JoinColumn(name="usuario_id",nullable=false) private Usuario usuario; @ManyToOne @JoinColumn(name="organizacion_id",nullable=false) private Organizacion organizacion; @ManyToOne @JoinColumn(name="rol_id",nullable=false) private Rol rol; private String estado="ACTIVO"; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); public Usuario getUsuario(){return usuario;} public Organizacion getOrganizacion(){return organizacion;} public Rol getRol(){return rol;} }
